#include <iostream>

// const int werte[] bedeutet hier dasselbe wie const int* werte.
int summe(const int* werte, int anzahl) {
    std::cout << "sizeof Zeiger: " << sizeof(werte) << std::endl;

    int s = 0;
    for (int i = 0; i < anzahl; ++i) {
        s += werte[i];
    }
    return s;
}

int main() {
    int messwerte[4] = {12, 7, 30, 5};

    std::cout << "sizeof im main: " << sizeof(messwerte) << std::endl;

    int ergebnis = summe(messwerte, 4);
    std::cout << "Summe: " << ergebnis << std::endl;
    return 0;
}

