#include <iostream>
#include <vector>

int main() {
    std::vector<int> messwerte = {42, 38, 51, 47, 39};

    int summe = 0;
    for (int wert : messwerte) {
        summe += wert;
    }

    double durchschnitt = static_cast<double>(summe) / messwerte.size();

    std::cout << "Summe: " << summe << std::endl;
    std::cout << "Durchschnitt: " << durchschnitt << std::endl;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<std::string> namen = {"weber", "mueller", "schmidt", "fischer"};

    std::sort(namen.begin(), namen.end());

    std::string gesucht = "mueller";
    auto position = std::find(namen.begin(), namen.end(), gesucht);

    if (position != namen.end()) {
        namen.erase(position);
        std::cout << gesucht << " wurde entfernt." << std::endl;
    } else {
        std::cout << gesucht << " ist nicht in der Liste." << std::endl;
    }

    for (const std::string& n : namen) {
        std::cout << n << std::endl;
    }
    return 0;
}
